/* eslint-disable */
<!--frontend/ src/views/login/RegisterPage.vue -->
<template>
  <div class="register-container">
    <div class="register-wrapper">
      <div class="register-form-container">
        <div class="register-header">
          <img :src="logo" alt="团团赚拼购" class="logo" />
          <h2>用户注册</h2>
        </div>

        <El-form
          ref="registerFormRef"
          :model="registerForm"
          :rules="registerRules"
          class="register-form"
        >
          <El-form-item prop="username">
            <El-input
              v-model="registerForm.username"
              placeholder="用户名"
              clearable
              :disabled="loading"
            >
              <template #prefix>
                <El-icon><User /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="nickname">
            <El-input
              v-model="registerForm.nickname"
              placeholder="昵称"
              clearable
              :disabled="loading"
            >
              <template #prefix>
                <El-icon><User /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="password">
            <El-input
              v-model="registerForm.password"
              type="password"
              placeholder="密码"
              show-password
              :disabled="loading"
            >
              <template #prefix>
                <El-icon><Lock /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="confirmPassword">
            <El-input
              v-model="registerForm.confirmPassword"
              type="password"
              placeholder="确认密码"
              show-password
              :disabled="loading"
            >
              <template #prefix>
                <El-icon><Lock /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item prop="paymentPassword">
            <El-input
              v-model="registerForm.paymentPassword"
              type="password"
              placeholder="支付密码"
              show-password
              :disabled="loading"
            >
              <template #prefix>
                <El-icon><Lock /></El-icon>
              </template>
            </El-input>
          </El-form-item>

          <El-form-item>
            <El-button
              type="primary"
              class="register-btn"
              round
              block
              :loading="loading"
              @click="handleRegister"
            >
              {{ loading ? '注册中...' : '注 册' }}
            </El-button>
          </El-form-item>

          <div class="register-footer">
            <El-link type="primary" @click="$router.push('/login')" :disabled="loading">
              已有账号？立即登录
            </El-link>
          </div>
        </El-form>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref } from "vue";
import { User, Lock } from "@element-plus/icons-vue";
import { ElMessage } from "element-plus";
import { useRouter } from "vue-router";
import userStore from "@/store/userStore";

const logo = "/assets/logo.png";
const router = useRouter();
const loading = ref(false);

const registerFormRef = ref(null);
const registerForm = ref({
  username: "",
  nickname: "",
  password: "",
  confirmPassword: "",
  paymentPassword: "",
});

const registerRules = {
  username: [
    { required: true, message: "请输入用户名", trigger: "blur" },
    { min: 3, message: "用户名至少需要3个字符", trigger: "blur" }
  ],
  nickname: [
    { required: true, message: "请输入昵称", trigger: "blur" },
    { min: 2, message: "昵称至少需要2个字符", trigger: "blur" }
  ],
  password: [
    { required: true, message: "请输入密码", trigger: "blur" },
    { min: 6, message: "密码至少需要6个字符", trigger: "blur" },
  ],
  confirmPassword: [
    { required: true, message: "请确认密码", trigger: "blur" },
    {
      validator: (rule, value, callback) => {
        if (value !== registerForm.value.password) {
          callback(new Error("两次密码输入不一致"));
        } else {
          callback();
        }
      },
      trigger: "blur",
    },
  ],
  paymentPassword: [
    { required: true, message: "请输入支付密码", trigger: "blur" },
    { min: 6, message: "支付密码至少需要6个字符", trigger: "blur" },
    {
      validator: (rule, value, callback) => {
        if (value === registerForm.value.password) {
          callback(new Error("支付密码不能与登录密码相同"));
        } else {
          callback();
        }
      },
      trigger: "blur",
    }
  ],
};

const handleRegister = () => {
  if (loading.value) return;

  registerFormRef.value.validate(async (valid) => {
    if (valid) {
      loading.value = true;
      try {
        await userStore.actions.register(null, {
          username: registerForm.value.username,
          password: registerForm.value.password,
          nickname: registerForm.value.nickname,
          paymentPassword: registerForm.value.paymentPassword,
        });

        ElMessage.success({
          message: "注册成功！正在跳转到登录页面...",
          duration: 2000
        });

        setTimeout(() => {
          router.push("/login");
        }, 2000);

      } catch (error) {
        console.error("注册错误:", error);
        ElMessage.error({
          message: error.message || "注册失败，请稍后重试",
          duration: 3000
        });
      } finally {
        loading.value = false;
      }
    }
  });
};
</script>

<style lang="scss" scoped>
.register-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background: linear-gradient(135deg, #f3f4f6, #e4e7ec);
}

.register-wrapper {
  background: white;
  border-radius: 10px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  padding: 30px;
  width: 400px;
}

.register-header {
  margin-bottom: 20px;
  text-align: center;

  .logo {
    width: 120px;
    height: auto;
    margin-bottom: 15px;
  }

  h2 {
    color: #2c3e50;
    font-size: 24px;
    margin: 0;
  }
}

.register-form {
  margin-top: 20px;
}

.register-footer {
  margin-top: 15px;
  text-align: center;
}

:deep(.el-input__wrapper) {
  border-radius: 20px;
}

:deep(.el-button) {
  height: 40px;
  font-size: 16px;
}
</style>
